class Poll:
    def __init__(self, question: str) -> None:
        self.question = question
        self._options = []          # options in the order they were added
        self._votes = {}            # voter -> option
        self._counts = {}           # option -> vote count

    def add_option(self, option: str) -> None:
        if option not in self._counts:
            self._options.append(option)
            self._counts[option] = 0

    def vote(self, voter: str, option: str) -> None:
        if voter in self._votes:
            raise ValueError(f"Voter '{voter}' has already voted.")
        if option not in self._counts:
            raise ValueError(f"Unknown option: '{option}'")
        self._votes[voter] = option
        self._counts[option] += 1

    def winner(self) -> str | None:
        if len(self._votes) < 3:
            return None

        best_option = None
        best_count = -1
        # Iterate in insertion order; ties resolved by last added winning,
        # so use >= to let later options override on equal count.
        for option in self._options:
            count = self._counts[option]
            if count >= best_count:
                best_count = count
                best_option = option

        return best_option
